#!/usr/bin/env bash
# Generated by kubegen from podman/kind-podman.yaml - re-generate instead of editing.
# Creates the kind cluster "dev-podman".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need podman https://podman.io/docs/installation
need kind 'https://kind.sigs.k8s.io/docs/user/quick-start/#installation'
need kubectl https://kubernetes.io/docs/tasks/tools/
[ "$missing" -eq 0 ] || exit 127

echo '==> Checking Podman'
# kind uses Docker unless told otherwise.
export KIND_EXPERIMENTAL_PROVIDER=podman
podman info >/dev/null 2>&1 || die "Podman is installed but not usable; on macOS/Windows run: podman machine start"

echo '==> Creating kind cluster dev-podman'
CONFIG_FILE="$(mktemp)"
trap 'rm -f "$CONFIG_FILE"' EXIT
cat > "$CONFIG_FILE" <<'KUBEGEN_EOF'
kind: Cluster
apiVersion: kind.x-k8s.io/v1alpha4
nodes:
  - role: control-plane
    extraPortMappings:
      - containerPort: 30080
        hostPort: 8080
      - containerPort: 30443
        hostPort: 8443
  - role: worker
  - role: worker
KUBEGEN_EOF
kind create cluster --name dev-podman \
  --config "$CONFIG_FILE" \
  --image kindest/node:v1.33.1 \
  --wait 120s

echo '==> Verifying access to dev-podman'
kubectl get nodes -o wide

echo "Cluster dev-podman is ready."
